import{c as s,ah as e,L as a,O as l}from"./chunks/framework.YKVbmyBD.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"web-src/fovlin-notes/linux-guide/configure-system/files-manage.md","filePath":"web-src/fovlin-notes/linux-guide/configure-system/files-manage.md"}'),d={name:"web-src/fovlin-notes/linux-guide/configure-system/files-manage.md"};function t(p,i,o,h,c,n){return e(),a("div",null,[...i[0]||(i[0]=[l('<h2 id="权限管理" tabindex="-1">权限管理 <a class="header-anchor" href="#权限管理" aria-label="Permalink to “权限管理”">​</a></h2><p>使用 <code>ls -l</code> 命令时，会输出文件的基本信息，其中包含文件的权限信息：</p><div class="language-log"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">drwxr-xr-x  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fovlin fovlin </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  4月17日 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">00:37</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> docs</span></span></code></pre></div><p>从左到右依次为：</p><hr><p><code>文件权限</code> <code>我也不知道是啥</code> <code>所有者</code> <code>所有组</code> <code>文件大小(不会显示目录大小)</code> <code>最后访问日期</code> <code>最后访问时间</code> <code>文件名称</code></p><hr><h3 id="更改文件权限" tabindex="-1">更改文件权限 <a class="header-anchor" href="#更改文件权限" aria-label="Permalink to “更改文件权限”">​</a></h3><p>文件权限 <code>drwxr-xr-x</code> 前一个字符表示文件类型，常见字符对应的文件类型如下：</p><ul><li><p><code>-</code>: 普通文件</p></li><li><p><code>d</code>: 目录</p></li><li><p><code>l</code>: 链接</p></li><li><p><code>c</code>: 字符设备文件</p></li><li><p><code>b</code>: 块设备文件</p></li><li><p><code>s</code>: 套接字文件</p></li><li><p><code>p</code>: 管道文件</p></li></ul><p>文件权限 <code>drwxr-xr-x</code> 第 2-4 、 5-7 、 8-10 个字符分别表示所有者权限、所有组权限、其他用户权限，三个字符分别代表：</p><ul><li><p><code>r</code>: 读权限</p></li><li><p><code>w</code>: 写权限</p></li><li><p><code>x</code>: 执行权限</p></li></ul><p>使用 <code>chmod</code> 可以改变文件权限，用法如下：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [选项] 权限信息 文件名</span></span></code></pre></div><blockquote><p>当权限不足时可以使用超级管理员进行操作。</p></blockquote><p>一般常用数字模式来表示权限：</p><ul><li><p><code>x</code>: 1</p></li><li><p><code>w</code>: 2</p></li><li><p><code>r</code>: 4</p></li></ul><p>将需要的权限对应的数字加和即可表示单个权限。</p><p>一个文件的权限信息由三位数字，也就是三个权限组成，分别表示所有者权限、所有组权限、其他用户权限。</p><p>例如将文件 script.sh 改为所有者可读可执行可写，同用户组可读可执行，其他用户仅执行，执行以下命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 751</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script.sh</span></span></code></pre></div><p>将整个目录 docs 递归改为所有者可读可执行可写，同用户组可读可执行，其他用户仅执行，执行以下命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 751</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span></code></pre></div><blockquote><p>可执行在目录中表示能否进入目录。</p></blockquote>',24)])])}const g=s(d,[["render",t]]);export{k as __pageData,g as default};
